cat > /tmp/test-frostbite.cjs <<'EOF'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1280,height:900}});
 page.on('console',m=>{if(m.type()==='error') console.error('console',m.text())});
 page.on('pageerror',e=>console.error('pageerror',e.message));
 await page.goto('http://localhost:3002');
 await page.screenshot({path:'/tmp/frostbite-intro.jpg',type:'jpeg',quality:75});
 await page.getByText('BEGIN PROTOCOL').click();
 await page.getByText('Search the body').click();
 await page.getByText('Read the shift log').click();
 await page.getByText('Open processing door').click();
 await page.getByText('Take the wire cutters').click();
 await page.getByText('Inspect relay stencil').click();
 await page.getByText('Unlock control vestibule').click();
 await page.getByText('Take the master keycard').click();
 await page.getByText('Read the grease-pencil note').click();
 await page.getByText('Open breaker cabinet').click();
 await page.locator('[data-wire="1"]').click();
 await page.getByText('ENGAGE FAILSAFE').click();
 await page.getByText('Use the north exit').click();
 await page.waitForTimeout(100);
 console.log('ending:', await page.locator('.modal-card h2').textContent());
 await page.screenshot({path:'/tmp/frostbite-win.jpg',type:'jpeg',quality:75});
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
EOF
node /tmp/test-frostbite.cjs

